:root {
  --bg: rgba(10, 14, 24, 0.82);
  --bg-solid: #0b101b;
  --line: rgba(140, 170, 210, 0.16);
  --text: #dbe4f0;
  --muted: #8193ab;
  --accent: #6fb6ff;
  --pha: #ffa23d;
  --risk: #ff3355;
  --radius: 10px;
  --font: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  color-scheme: dark;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: #03050b;
  color: var(--text);
  font: 13px/1.45 var(--font);
}

#view { position: fixed; inset: 0; }
#view canvas { display: block; }

button, input, select { font: inherit; color: inherit; }
.muted { color: var(--muted); }
[hidden] { display: none !important; }

.panel, .topbar, .timebar, #scalebar {
  background: var(--bg);
  backdrop-filter: blur(10px);
  border: 1px solid var(--line);
  border-radius: var(--radius);
}

/* ---------- top bar */
.topbar {
  position: fixed;
  top: 10px;
  left: 10px;
  right: 10px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 12px;
  z-index: 3;
}
.brand strong { font-size: 15px; letter-spacing: 0.02em; margin-right: 12px; }
.top-actions { display: flex; gap: 6px; }

.btn {
  background: rgba(120, 160, 220, 0.1);
  border: 1px solid var(--line);
  border-radius: 7px;
  padding: 4px 10px;
  cursor: pointer;
  white-space: nowrap;
}
.btn:hover { background: rgba(120, 160, 220, 0.2); }
.btn.icon { width: 30px; padding: 4px 0; text-align: center; }
.btn.on { background: var(--accent); color: #04101f; border-color: var(--accent); }
.btn.wide { width: 100%; }

/* ---------- side panels */
#left {
  position: fixed;
  top: 64px;
  left: 10px;
  bottom: 96px;
  width: 300px;
  display: flex;
  flex-direction: column;
  z-index: 2;
}
#detail {
  position: fixed;
  top: 64px;
  right: 10px;
  bottom: 96px;
  width: 340px;
  overflow-y: auto;
  padding: 14px;
  z-index: 2;
}

.search { position: relative; padding: 10px 10px 6px; }
.search input {
  width: 100%;
  padding: 7px 10px;
  border-radius: 7px;
  border: 1px solid var(--line);
  background: rgba(0, 0, 0, 0.35);
}
.results {
  position: absolute;
  left: 10px;
  right: 10px;
  top: 44px;
  margin: 0;
  padding: 4px;
  list-style: none;
  max-height: 340px;
  overflow-y: auto;
  background: var(--bg-solid);
  border: 1px solid var(--line);
  border-radius: 8px;
  z-index: 5;
}
.results li {
  padding: 5px 8px;
  border-radius: 5px;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  gap: 8px;
}
.results li:hover, .results li.active { background: rgba(111, 182, 255, 0.15); }
.results .kind { color: var(--muted); font-size: 11px; }

.tabs { display: flex; gap: 4px; padding: 0 10px; border-bottom: 1px solid var(--line); }
.tabs button {
  background: none;
  border: 0;
  border-bottom: 2px solid transparent;
  padding: 6px 8px;
  cursor: pointer;
  color: var(--muted);
}
.tabs button.active { color: var(--text); border-bottom-color: var(--accent); }

.pane { overflow-y: auto; padding: 10px 12px 14px; flex: 1; }
.group { margin-bottom: 14px; }
.group-title {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--muted);
  margin: 6px 0 5px;
}
.val { color: var(--text); text-transform: none; letter-spacing: 0; }
input[type="range"] { width: 100%; accent-color: var(--accent); }

.seg { display: flex; flex-wrap: wrap; gap: 3px; }
.seg button {
  flex: 1 1 auto;
  background: rgba(120, 160, 220, 0.08);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 3px 7px;
  cursor: pointer;
  font-size: 12px;
}
.seg button.active { background: rgba(111, 182, 255, 0.25); border-color: var(--accent); }

.chips { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 7px; }
.chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 8px;
  border-radius: 99px;
  border: 1px solid var(--line);
  cursor: pointer;
  font-size: 12px;
  user-select: none;
}
.chip.off { opacity: 0.4; }
.dot { width: 8px; height: 8px; border-radius: 50%; display: inline-block; flex: none; }

.check { display: flex; align-items: center; gap: 6px; margin: 4px 0; cursor: pointer; }
.check select, .row select {
  background: rgba(0, 0, 0, 0.3);
  border: 1px solid var(--line);
  border-radius: 5px;
  font-size: 12px;
}
.row { display: flex; align-items: center; gap: 6px; margin-top: 6px; }

#legend { margin-top: 8px; font-size: 12px; }
#legend .item { display: flex; align-items: center; gap: 7px; margin: 2px 0; }
#legend .ramp { height: 8px; border-radius: 4px; margin: 4px 0 2px; }
#legend .ends { display: flex; justify-content: space-between; color: var(--muted); font-size: 11px; }

/* ---------- highlights */
.hl { margin-bottom: 16px; }
