  return { kind, idx: Number(idx) };
}

const kv = (rows: [string, string][]) =>
  `<dl class="kv">${rows.map(([k, v]) => `<dt>${k}</dt><dd>${v}</dd>`).join("")}</dl>`;

const deg = (x: number | null | undefined) => fmtNum(x, 2, "°");

