      ${kv([
        ["Palermo (cum / max)", `${s.ps_cum.toFixed(2)} / ${s.ps_max.toFixed(2)}`],
        ["Torino (max)", String(s.ts_max ?? "—")],
        ["Potential impacts", s.n_imp.toLocaleString()],
        ["Entry velocity", fmtNum(s.v_inf, 1, " km/s")],
